    [Fact]
    public void SharedFieldFormatterRetainsDecimalFallback()
    {
        Assert.Equal("1", DxpListMarkerFormatter.FormatNumber(1, NumberFormatValues.ThaiCounting));
        Assert.Equal("1000000000", DxpListMarkerFormatter.FormatNumber(1000000000, NumberFormatValues.ThaiCounting));
    }

